<template><div class="ui-kv-editor"><div v-for="(row,index) in modelValue" :key="row.id??index" class="ui-kv-editor__row"><UiTextField :model-value="row.key" :placeholder="keyPlaceholder" density="dense" @update:model-value="update(index,'key',$event)"/><UiTextField :model-value="row.value" :placeholder="valuePlaceholder" density="dense" @update:model-value="update(index,'value',$event)"/><UiIconButton icon="trash" label="删除" variant="danger" density="dense" @click="remove(index)"/></div><UiButton density="dense" variant="quiet" @click="add"><template #icon><Icon name="plus" size="sm"/></template>{{addLabel}}</UiButton></div></template>
<script setup lang="ts">import Icon from '@/components/icons/Icon.vue';import UiButton from './UiButton.vue';import UiIconButton from './UiIconButton.vue';import UiTextField from './UiTextField.vue';export interface UiKeyValueRow{id?:string|number;key:string;value:string}const props=withDefaults(defineProps<{modelValue:UiKeyValueRow[];keyPlaceholder?:string;valuePlaceholder?:string;addLabel?:string}>(),{keyPlaceholder:'字段名',valuePlaceholder:'字段值',addLabel:'添加一项'});const emit=defineEmits<{'update:modelValue':[UiKeyValueRow[]]}>();function update(index:number,field:'key'|'value',value:string){emit('update:modelValue',props.modelValue.map((row,i)=>i===index?{...row,[field]:value}:row))}function remove(index:number){emit('update:modelValue',props.modelValue.filter((_,i)=>i!==index))}function add(){emit('update:modelValue',[...props.modelValue,{key:'',value:''}])}</script>
<style scoped>.ui-kv-editor{display:grid;gap:6px}.ui-kv-editor__row{display:grid;grid-template-columns:minmax(110px,.7fr) minmax(160px,1.3fr) auto;gap:6px}@media(max-width:520px){.ui-kv-editor__row{grid-template-columns:1fr auto}.ui-kv-editor__row>:nth-child(2){grid-column:1}}</style>
